(async()=>{'use strict';const C=window.AcademyCore,$=id=>document.getElementById(id),KEY='walamort-academy-app-v1:'+new URL('.',location.href).pathname;let lessons=[],data={version:1,sessions:[],lessons:[],settings:{lang:'es',level:1,goal:'beginner',minutes:10,questions:5,volume:.55,instrument:'piano',notation:'solfege',chordNotation:'names',showOctave:false,autoAdvance:true,a4:440,tolerance:20}},tab='home',session=null,installPrompt=null,storageOK=true,ctx=null,voices=[],masters=[],timers=[],rhythm=null,swRegistration=null,rejectedData=null,audioEpoch=0,practiceGroup='reading',practiceQuery='',lessonQuery='',lessonFilter='all',courseLevel=1;
const T=(es,en,pt)=>data.settings.lang==='en'?en:data.settings.lang==='pt'?pt:es;
const H=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles={reading:['Lectura de notas','Note reading','Leitura de notas'],interval:['Intervalos','Intervals','Intervalos'],chord:['Acordes','Chords','Acordes'],scale:['Escalas','Scales','Escalas'],dictation:['Dictado melódico','Melodic dictation','Ditado melódico'],rhythm:['Precisión rítmica','Rhythm timing','Precisão rítmica']};
Object.assign(titles,{intervalTheory:['Intervalos en pentagrama','Intervals on the staff','Intervalos no pentagrama'],chordTheory:['Acordes en pentagrama','Chords on the staff','Acordes no pentagrama'],rhythmTheory:['Figuras y silencios','Note values and rests','Figuras e pausas'],rhythmDictation:['Dictado rítmico','Rhythm dictation','Ditado rítmico'],keys:['Armaduras','Key signatures','Armaduras'],progression:['Progresiones armónicas','Harmonic progressions','Progressões harmônicas'],intonation:['Entonación','Intonation','Entonação']});
const N=n=>C.displayNote(n,data.settings,data.settings.lang);
const kindTitle=k=>titles[k][['es','en','pt'].indexOf(data.settings.lang)];
const label=x=>{const map={major:['Mayor','Major','Maior'],minor:['Menor natural','Natural minor','Menor natural'],sus4:['Suspendido 4','Suspended 4','Suspenso 4'],dim:['Disminuido','Diminished','Diminuto'],aug:['Aumentado','Augmented','Aumentado'],dom7:['Séptima dominante','Dominant seventh','Sétima dominante'],maj7:['Séptima mayor','Major seventh','Sétima maior'],min7:['Séptima menor','Minor seventh','Sétima menor'],pentMajor:['Pentatónica mayor','Major pentatonic','Pentatônica maior'],pentMinor:['Pentatónica menor','Minor pentatonic','Pentatônica menor'],dorian:['Dórico','Dorian','Dórico'],mixolydian:['Mixolidio','Mixolydian','Mixolídio']};if(x==='minor'&&['chord','chordTheory'].includes(session?.kind))return T('Menor','Minor','Menor');return map[x]?.[['es','en','pt'].indexOf(data.settings.lang)]||window.AcademyDictionary.scales.find(v=>v.id===x)?.names[['es','en','pt'].indexOf(data.settings.lang)]||x;};
const intervalLabel=n=>{const a={1:['2ª menor','Minor 2nd','2ª menor'],2:['2ª mayor','Major 2nd','2ª maior'],3:['3ª menor','Minor 3rd','3ª menor'],4:['3ª mayor','Major 3rd','3ª maior'],5:['4ª justa','Perfect 4th','4ª justa'],6:['Tritono','Tritone','Trítono'],7:['5ª justa','Perfect 5th','5ª justa'],8:['6ª menor','Minor 6th','6ª menor'],9:['6ª mayor','Major 6th','6ª maior'],10:['7ª menor','Minor 7th','7ª menor'],11:['7ª mayor','Major 7th','7ª maior'],12:['Octava','Octave','Oitava']};return a[n][['es','en','pt'].indexOf(data.settings.lang)];};
function say(text){$('globalStatus').textContent=text;}
function save(){if(rejectedData!==null){say(T('El historial anterior no es válido y se ha conservado intacto. Exporta el original desde Ajustes.','Previous history is invalid and was kept untouched. Export the original in Settings.','O histórico anterior é inválido e foi preservado. Exporte o original em Ajustes.'));return false;}try{localStorage.setItem(KEY,JSON.stringify(data));storageOK=true;return true}catch{storageOK=false;say(T('No se pudo guardar. Exporta una copia antes de salir.','Could not save. Export a backup before leaving.','Não foi possível salvar. Exporte uma cópia antes de sair.'));return false;}}
function stop(preserveVoice=false){audioEpoch++;if(preserveVoice)window.AcademyVoice?.pause();else window.AcademyVoice?.stop();timers.forEach(clearTimeout);timers=[];for(const v of voices){try{v.stop()}catch{}}voices=[];for(const m of masters)m.disconnect();masters=[];rhythm=null;}
async function audio(){if(!ctx)ctx=new (window.AudioContext||window.webkitAudioContext)();await ctx.resume();return ctx;}
function tone(midi,when,duration=.5,gain=1){if(!ctx||data.settings.volume===0)return;const preset={piano:{h:[1,.45,.22,.1,.05],a:.008,d:true},guitar:{h:[1,.65,.3,.16,.12,.06],a:.005,d:true},flute:{h:[1,.07,.025],a:.04,d:false},violin:{h:[1,.65,.45,.3,.2,.14,.1],a:.06,d:false}}[data.settings.instrument]||{h:[1,.3,.1],a:.01,d:true};const master=ctx.createGain(),o=ctx.createOscillator(),imag=new Float32Array(preset.h.length+1);masters.push(master);preset.h.forEach((v,i)=>imag[i+1]=v);o.setPeriodicWave(ctx.createPeriodicWave(new Float32Array(imag.length),imag));o.frequency.value=(data.settings.a4||440)*2**((midi-69)/12);const peak=data.settings.volume*.18*gain,attack=Math.min(preset.a,duration/4);master.gain.setValueAtTime(0,when);master.gain.linearRampToValueAtTime(peak,when+attack);if(preset.d)master.gain.exponentialRampToValueAtTime(Math.max(.0001,peak*.25),when+duration*.7);else master.gain.setValueAtTime(peak*.8,when+duration*.7);master.gain.linearRampToValueAtTime(0,when+duration);o.connect(master);master.connect(ctx.destination);o.start(when);o.stop(when+duration+.02);voices.push(o);o.onended=()=>{o.disconnect();master.disconnect();voices=voices.filter(v=>v!==o);masters=masters.filter(v=>v!==master);};}

async function hear(q){stop();const ticket=audioEpoch;try{await audio();if(ticket!==audioEpoch)return;const start=ctx.currentTime+.08;if(q.kind==='rhythmDictation'){window.AcademyNotation.onsets(q.durations).forEach(p=>tone(84,start+p*60/q.bpm,.1,.7));}else if(q.kind==='rhythmTheory'){tone(72,start,Math.abs(q.figure)*.55,.7);}else if(q.kind==='progression'){q.progression.forEach((chord,i)=>chord.forEach(n=>tone(n,start+i*.85,.75,.55)));}else if(q.kind==='rhythm'){for(const p of q.answer)tone(84,start+p*60/q.bpm,.09,.8);}else if((q.kind==='chord'||q.kind==='chordTheory')){q.notes.forEach(n=>tone(n,start,1,.65));}else q.notes.forEach((n,i)=>tone(n,start+i*(q.kind==='scale'?.25:.6),.5));}catch{say(T('No se pudo iniciar el audio. Vuelve a pulsar Escuchar.','Audio could not start. Tap Listen again.','Não foi possível iniciar o áudio. Toque em Ouvir novamente.'));}}
async function demonstrate(steps,seconds=.55,onStep=()=>{},durations=null){stop();const ticket=audioEpoch;try{await audio();if(ticket!==audioEpoch)return;let offset=0;const begin=ctx.currentTime+.06;steps.forEach((step,i)=>{const notes=Array.isArray(step)?step:[step],length=(durations?.[i]||1)*seconds;for(const n of notes)tone(n,begin+offset,Math.max(.06,length*.85),notes.length>1?.55:.8);timers.push(setTimeout(()=>{if(ticket===audioEpoch)onStep(i);},(begin+offset-ctx.currentTime)*1000));offset+=length;});timers.push(setTimeout(()=>{if(ticket===audioEpoch)onStep(-1);},(begin+offset-ctx.currentTime)*1000));}catch{say(T('No se pudo iniciar el sonido. Vuelve a pulsar.','Could not start sound. Tap again.','Não foi possível iniciar o som. Toque novamente.'));}}
function dictionary(){window.AcademyDictionary.show($('view'),{T,H,settings:()=>data.settings,language:()=>data.settings.lang,note:N,play:demonstrate,practice:()=>start('scale',3),stop,soundControls,bindSoundControls,back:()=>render('lessons')});}
const card=(title,body,action)=>`<article class="card"><h3>${H(title)}</h3><p>${H(body)}</p>${action}</article>`;
const b=(text,attrs='')=>`<button type="button" ${attrs}>${H(text)}</button>`;
function connection(){const cached=!!navigator.serviceWorker?.controller;$('connection').textContent=navigator.onLine?T('En línea','Online','On-line')+(cached?T(' · núcleo listo sin conexión',' · core ready offline',' · núcleo pronto off-line'):''):T('Sin conexión · contenido guardado','Offline · saved content','Off-line · conteúdo salvo');}
function render(next=tab){stop();$('view').dataset.screen=next;tab=next;session=null;$('globalStatus').textContent='';const names={home:T('Inicio','Home','Início'),lessons:T('Aprender','Learn','Aprender'),practice:T('Practicar','Practice','Praticar'),progress:T('Progreso','Progress','Progresso'),settings:T('Ajustes','Settings','Ajustes')};document.documentElement.lang=data.settings.lang==='pt'?'pt-BR':data.settings.lang;for(const e of document.querySelectorAll('[data-tab]')){e.textContent=names[e.dataset.tab];e.setAttribute('aria-current',(e.dataset.tab===tab||(tab==='dictionary'&&e.dataset.tab==='lessons'))?'page':'false');}$('install').textContent=T('Instalar','Install','Instalar');connection();if(tab==='home')home();if(tab==='lessons')lessonList();if(tab==='practice')practiceMenu();if(tab==='progress')progress();if(tab==='settings')settings();if(tab==='dictionary')dictionary();window.scrollTo(0,0);$('main').focus({preventScroll:true});}
function home(){const routine=C.routine(data);$('view').innerHTML=`<p class="eyebrow">${T('TU MÚSICA, UN POCO CADA DÍA','YOUR MUSIC, A LITTLE EVERY DAY','SUA MÚSICA, UM POUCO A CADA DIA')}</p><h2>${T('Escucha. Entiende. Practica.','Listen. Understand. Practice.','Ouça. Entenda. Pratique.')}</h2><p>${T('Teoría y ejercicios en tu bolsillo. Sin cuenta, sin anuncios y con progreso en este dispositivo.','Theory and exercises in your pocket. No account, no ads, with progress on this device.','Teoria e exercícios no bolso. Sem conta, sem anúncios, com progresso neste dispositivo.')}</p><section class="panel"><h3>${T('Tu rutina de hoy','Your routine today','Sua rotina de hoje')} · ${data.settings.minutes} min</h3><p class="hint">${T('Tiempo orientativo. Primero aparecen las habilidades menos practicadas o con resultados más bajos.','Suggested time. Least-practiced or lower-scoring skills appear first.','Tempo sugerido. Primeiro aparecem as habilidades menos praticadas ou com resultados menores.')}</p><div class="actions">${routine.map(k=>b(kindTitle(k),`data-start="${k}" class="primary"`)).join('')}</div></section><div class="grid">${card(T(lessons.length+' lecciones para comprender',lessons.length+' lessons to understand',lessons.length+' lições para compreender'),T('Notas, claves, escalas, acordes, ritmo y creación.','Notes, clefs, scales, chords, rhythm and creation.','Notas, claves, escalas, acordes, ritmo e criação.'),b(T('Abrir lecciones','Open lessons','Abrir lições'),'data-go="lessons"'))}${card(T('Doce maneras de practicar','Twelve ways to practice','Doze formas de praticar'),T('Sesiones breves con dificultad progresiva y explicación.','Short sessions with progressive difficulty and feedback.','Sessões curtas com dificuldade progressiva e explicação.'),b(T('Elegir ejercicio','Choose exercise','Escolher exercício'),'data-go="practice"'))}</div><div class="actions">${b(T('Diccionario de escalas · piano y guitarra','Scale dictionary · piano and guitar','Dicionário de escalas · piano e violão'),'data-go="dictionary"')}</div><p class="hint">${T('La app incluye su propio historial. El historial de las herramientas web se consulta por separado en la página.','The app has its own history. Existing web-tool history is viewed separately on the website.','A app tem seu próprio histórico. O histórico das ferramentas web é consultado separadamente no site.')}</p>`;bindRoutes();}
function bindRoutes(){document.querySelectorAll('[data-go]').forEach(e=>e.onclick=()=>render(e.dataset.go));document.querySelectorAll('[data-start]').forEach(e=>e.onclick=()=>start(e.dataset.start,Number(e.dataset.level)||data.settings.level));}
const courseName=level=>({1:T('Desde cero','From scratch','Do zero'),2:T('Desarrollo','Development','Desenvolvimento'),3:T('Profundizar','Go deeper','Aprofundar')}[level]);
function lessonList(){const l=data.settings.lang;$('view').dataset.screen='lessons';$('view').innerHTML=`<h2>${T('Aprender y explorar','Learn and explore','Aprender e explorar')}</h2><div class="practice-filters"><button type="button" aria-pressed="true">${T('Rutas guiadas','Guided paths','Trilhas guiadas')}</button>${b(T('Diccionario · piano y guitarra','Dictionary · piano and guitar','Dicionário · piano e violão'),'data-go="dictionary"')}</div><div class="practice-filters" role="group" aria-label="${T('Ruta de aprendizaje','Learning path','Trilha de aprendizagem')}">${[1,2,3,0].map(n=>b(n?courseName(n):T('Todas','All','Todas'),`data-course="${n}" aria-pressed="${courseLevel===n}"`)).join('')}</div><div id="courseSummary"></div><div class="lesson-filters"><label><span class="sr-only">${T('Buscar en todas las rutas','Search all paths','Buscar em todas as trilhas')}</span><input type="search" id="lessonSearch" placeholder="${T('Buscar en todas las rutas…','Search all paths…','Buscar em todas as trilhas…')}" value="${H(lessonQuery)}"></label><label><span class="sr-only">${T('Estado de lecciones','Lesson status','Estado das lições')}</span><select id="lessonFilter">${[['all',T('Todas','All','Todas')],['pending',T('Pendientes','Not completed','Pendentes')],['done',T('Completadas','Completed','Concluídas')]].map(([v,t])=>`<option value="${v}" ${v===lessonFilter?'selected':''}>${t}</option>`).join('')}</select></label></div><p id="lessonCount" class="small muted" role="status"></p><div id="lessonList" class="lesson-list"></div>`;const draw=()=>{const query=searchText(lessonQuery.trim()),route=lessons.filter(x=>!courseLevel||x.level===courseLevel),done=route.filter(x=>data.lessons.includes(x.id)).length,next=route.find(x=>!data.lessons.includes(x.id));$('courseSummary').innerHTML=`<p class="small">${done}/${route.length} ${T('completadas en esta ruta','completed in this path','concluídas nesta trilha')}</p><progress value="${done}" max="${route.length}" aria-label="${T('Progreso de la ruta','Path progress','Progresso da trilha')}"></progress><p class="hint">${courseLevel===1?T('Sonido, pulso, lectura, primeras escalas y acordes. Empieza aquí aunque nunca hayas estudiado música.','Sound, beat, reading, first scales and chords. Start here with no previous music study.','Som, pulso, leitura, primeiras escalas e acordes. Comece aqui mesmo sem estudo musical anterior.'):courseLevel===2?T('Conecta lectura, oído y armonía. Repasa conceptos y aplica variaciones con ejemplos tocables.','Connect reading, ear and harmony. Review ideas and apply variations with playable examples.','Conecte leitura, ouvido e harmonia. Revise conceitos e aplique variações com exemplos tocáveis.'):T('Explora recursos armónicos y rítmicos con ejemplos analizados. Puedes entrar directamente y volver a fundamentos cuando lo necesites.','Explore harmonic and rhythmic resources with analyzed examples. Enter directly and revisit fundamentals whenever needed.','Explore recursos harmônicos e rítmicos com exemplos analisados. Entre diretamente e retome fundamentos quando precisar.')}</p>${!query&&next?b(T('Continuar: ','Continue: ','Continuar: ')+next.text[l].title,`data-lesson="${next.id}" class="path-next"`):''}`;const visible=lessons.filter(x=>(query||!courseLevel||x.level===courseLevel)&&(lessonFilter==='all'||data.lessons.includes(x.id)===(lessonFilter==='done'))&&(!query||searchText(x.text[l].title+' '+x.text[l].body).includes(query)));$('lessonCount').textContent=visible.length+' '+(visible.length===1?T('lección','lesson','lição'):T('lecciones','lessons','lições'));$('lessonList').innerHTML=visible.map(x=>`<button class="exercise-row" type="button" data-lesson="${x.id}"><span><strong>${H(x.text[l].title)}</strong><span class="row-description">${courseName(x.level)} · ${x.minutes} min · ${data.lessons.includes(x.id)?T('Completada','Completed','Concluída'):T('Pendiente','Not completed','Pendente')}</span></span><span aria-hidden="true">›</span></button>`).join('')||`<p>${T('No hay lecciones con estos filtros.','No lessons match these filters.','Nenhuma lição com estes filtros.')}</p>`;document.querySelectorAll('[data-lesson]').forEach(e=>e.onclick=()=>showLesson(e.dataset.lesson));document.querySelectorAll('[data-course]').forEach(e=>e.setAttribute('aria-pressed',String(!query&&Number(e.dataset.course)===courseLevel)));};$('lessonSearch').oninput=e=>{lessonQuery=e.target.value;draw();};$('lessonFilter').onchange=e=>{lessonFilter=e.target.value;draw();};document.querySelectorAll('[data-course]').forEach(e=>e.onclick=()=>{courseLevel=Number(e.dataset.course);lessonQuery='';$('lessonSearch').value='';draw();});bindRoutes();draw();}
function showLesson(id){stop();$('view').dataset.screen='lesson';window.scrollTo(0,0);const item=lessons.find(x=>x.id===id),x=item.text[data.settings.lang],opts=C.shuffle(x.options.map((text,index)=>({text,index})));let task=0;const next=lessons.filter(v=>v.level===item.level).find((v,i,a)=>i>a.findIndex(v=>v.id===id));$('view').innerHTML=`${b(T('← Rutas','← Paths','← Trilhas'),'id="backLessons"')}<p class="eyebrow">${H(courseName(item.level))} · ${item.minutes} min</p><h2>${H(x.title)}</h2><div class="panel lesson-body">${H(x.body)}</div>${item.demo?`<section class="panel lesson-demo"><h3>${T('Escucha y observa','Listen and observe','Ouça e observe')}</h3>${soundControls()}<div id="lessonDemoScore"></div><div class="demo-notes" id="demoNotes"></div><p id="demoPosition" class="small" role="status"></p><div class="actions">${b(T('Reproducir ejemplo','Play example','Reproduzir exemplo'),'id="lessonPlay" class="primary"')}${b(T('Detener','Stop','Parar'),'id="lessonStop"')}</div><p class="hint">${T('Pulsa un sonido para aislarlo. El timbre elegido se usa también en esta demostración.','Tap a sound to isolate it. Your chosen timbre also applies to this demonstration.','Toque um som para isolá-lo. O timbre escolhido também vale nesta demonstração.')}</p></section>`:''}${(x.sections||[]).map((part,i)=>`<details class="panel lesson-detail" ${i===0?'open':''}><summary>${H(part.heading)}</summary><p>${H(part.body)}</p></details>`).join('')}${x.steps?`<section class="panel"><h3>${T('Practica paso a paso','Practice step by step','Pratique passo a passo')}</h3><p id="guidedTask" role="status"></p><div class="actions">${b(T('Anterior','Previous','Anterior'),'id="taskPrevious"')}${b(T('Siguiente paso','Next step','Próximo passo'),'id="taskNext"')}</div><p class="hint">${T('Estos pasos son práctica libre y autoevaluación. El repaso de abajo comprueba un concepto.','These steps are free practice and self-assessment. The review below checks a concept.','Estes passos são prática livre e autoavaliação. A revisão abaixo verifica um conceito.')}</p>${item.practice?b(T('Abrir entrenamiento','Open training','Abrir treino'),`data-start="${item.practice}" data-level="${item.practiceLevel||item.level}"`):''}${['intonation-basics','tuning-cents'].includes(id)?b(T('Abrir entonación','Open intonation','Abrir entonação'),'id="lessonVoice"'):''}${b(T('Explorar escalas en piano y guitarra','Explore scales on piano and guitar','Explorar escalas no piano e violão'),'data-go="dictionary"')}</section>`:''}<section class="panel"><h3>${T('Comprueba y comprende','Check and understand','Confira e compreenda')}</h3><p>${H(x.question)}</p><div class="choices">${opts.map(o=>b(o.text,`data-review="${o.index}"`)).join('')}</div><p id="reviewFeedback" class="feedback" role="status"></p>${b(next?T('Guardar y seguir','Save and continue','Salvar e continuar'):T('Completar ruta','Complete path','Concluir trilha'),'id="completeLesson" class="primary" disabled')}</section>`;$('backLessons').onclick=()=>{stop();lessonList();};bindRoutes();if($('lessonVoice'))$('lessonVoice').onclick=()=>voiceView('intonation');if(x.steps){const taskView=()=>{$('guidedTask').textContent=`${task+1}/${x.steps.length} · ${x.steps[task]}`;$('taskPrevious').disabled=task===0;$('taskNext').disabled=task===x.steps.length-1;};$('taskPrevious').onclick=()=>{task--;taskView();};$('taskNext').onclick=()=>{task++;taskView();};taskView();}if(item.demo)lessonDemo(item);document.querySelectorAll('[data-review]').forEach(e=>e.onclick=()=>{const good=Number(e.dataset.review)===x.answer;e.classList.add(good?'good':'bad');$('reviewFeedback').textContent=(good?T('Correcto. ','Correct. ','Correto. '):T('Revisa este ejemplo: ','Review this example: ','Revise este exemplo: '))+(x.why||x.body);if(good)$('completeLesson').disabled=false;});$('completeLesson').onclick=()=>{if(!data.lessons.includes(id))data.lessons.push(id);save();stop();if(next)showLesson(next.id);else lessonList();};}
function lessonDemo(item){const d=item.demo,steps=d.rhythm?d.rhythm.map((v,i)=>[d.accents?.includes(i)?88:82]):d.notes.map(n=>Array.isArray(n)?n:[n]),durations=d.rhythm?.map(Math.abs),demoNote=n=>d.flats?.includes(n%12)?N(n+1).replace(/(-?\d+)?$/,'♭$1'):N(n),labels=steps.map((notes,i)=>d.rhythm?String(i+1):notes.map(demoNote).join('–'));$('lessonDemoScore').innerHTML=d.rhythm?window.AcademyNotation.rhythm(d.rhythm,T('Ejemplo rítmico','Rhythm example','Exemplo rítmico'),false,d.meter||[4,4]):steps.every(n=>n.length===1)?window.AcademyNotation.melody(steps.map(n=>n[0]),T('Ejemplo de alturas: solo alturas, no duración','Pitch example: pitch only, not duration','Exemplo de alturas: somente alturas, não duração'),d.flats||[]):'';if(!d.rhythm&&steps.length>8)$('lessonDemoScore').querySelector('svg')?.setAttribute('style','min-width:'+steps.length*48+'px');$('demoNotes').innerHTML=labels.map((name,i)=>b(name,`data-demo="${i}"`)).join('');const mark=i=>{document.querySelectorAll('[data-demo]').forEach(e=>e.classList.toggle('is-playing',Number(e.dataset.demo)===i));$('demoPosition').textContent=i<0?'':T('Sonido','Sound','Som')+' '+(i+1)+'/'+steps.length;};$('lessonPlay').onclick=()=>demonstrate(steps,d.rhythm ? .5 : .65,mark,durations);$('lessonStop').onclick=()=>{stop();mark(-1);};document.querySelectorAll('[data-demo]').forEach(e=>e.onclick=()=>{const i=Number(e.dataset.demo);demonstrate([steps[i]],.75,j=>mark(j<0?-1:i));});bindSoundControls(key=>{mark(-1);if(['notation','showOctave'].includes(key))lessonDemo(item);});}
function soundControls(){return `<details class="panel"><summary>${T('Sonido, nombres y avance','Sound, naming and progression','Som, nomes e avanço')}</summary><div class="grid"><label>${T('Instrumento de práctica','Practice instrument','Instrumento de prática')}<select id="practiceInstrument">${[['piano','Piano'],['guitar',T('Guitarra','Guitar','Violão')],['flute',T('Flauta','Flute','Flauta')],['violin',T('Violín','Violin','Violino')]].map(([v,t])=>`<option value="${v}" ${data.settings.instrument===v?'selected':''}>${t}</option>`).join('')}</select></label><label>${T('Nombres de notas','Note naming','Nomes das notas')}<select id="noteNotation"><option value="solfege" ${data.settings.notation!=='letters'?'selected':''}>Do · Re · Mi</option><option value="letters" ${data.settings.notation==='letters'?'selected':''}>C · D · E</option></select></label><label>${T('Acordes','Chords','Acordes')}<select id="chordNotation"><option value="names" ${data.settings.chordNotation!=='symbols'?'selected':''}>${T('Nombre: mayor, menor…','Names: major, minor…','Nomes: maior, menor…')}</option><option value="symbols" ${data.settings.chordNotation==='symbols'?'selected':''}>${T('Cifrado: C, Cm, C7…','Symbols: C, Cm, C7…','Cifras: C, Cm, C7…')}</option></select></label></div><label class="check"><input type="checkbox" id="showOctave" ${data.settings.showOctave?'checked':''}>${T('Mostrar número de octava (opcional)','Show octave number (optional)','Mostrar número da oitava (opcional)')}</label><label class="check"><input type="checkbox" id="autoAdvance" ${data.settings.autoAdvance!==false?'checked':''}>${T('Avanzar automáticamente después de cada respuesta','Advance automatically after each answer','Avançar automaticamente após cada resposta')}</label><p class="hint">${T('Timbres sintetizados, disponibles sin conexión. El avance espera un poco más cuando hay un error para que puedas revisar la corrección.','Synthesized timbres, available offline. Advance waits longer after an error so you can review the correction.','Timbres sintetizados, disponíveis off-line. O avanço espera mais após um erro para você revisar a correção.')}</p></details>`;}
function bindSoundControls(onChange){for(const [id,key] of [['practiceInstrument','instrument'],['noteNotation','notation'],['chordNotation','chordNotation'],['showOctave','showOctave'],['autoAdvance','autoAdvance']]){const e=$(id);if(e)e.onchange=()=>{stop();data.settings[key]=e.type==='checkbox'?e.checked:e.value;save();onChange?.(key);};}}
function chordAnswer(x,q){if(session?.kind==='rhythmDictation')return T('Patrón','Pattern','Padrão')+' '+(q.options.indexOf(x)+1);if(!['chord','chordTheory'].includes(session?.kind))return label(x);if(data.settings.chordNotation==='symbols'){const root=C.displayNote(q.root||60,{notation:'letters'},'en');return root+({major:'',minor:'m',sus4:'sus4',dim:'dim',aug:'aug',dom7:'7',maj7:'maj7',min7:'m7'}[x]||'');}return label(x);}
function voiceView(mode){stop();$('view').dataset.screen='voice';tab='practice';session=null;window.AcademyVoice.show($('view'),{T,H,settings:()=>data.settings,note:N,exit:()=>render('practice'),pitchSettings:(a4,tolerance)=>{data.settings.a4=a4;data.settings.tolerance=tolerance;save();},reference:async n=>{const ticket=audioEpoch;try{await audio();if(ticket!==audioEpoch)return;tone(n,ctx.currentTime+.03,1);}catch{say(T('Audio no disponible.','Audio unavailable.','Áudio indisponível.'));}},silence:()=>{for(const v of voices){try{v.stop()}catch{}}},record:score=>{data.sessions.push({id:crypto.randomUUID(),kind:'intonation',level:data.settings.level,score,total:1,date:new Date().toISOString()});data.sessions=data.sessions.slice(-300);save();}},mode);window.scrollTo(0,0);}

function controls(){return `<div class="grid"><label>${T('Nivel','Level','Nível')}<select id="level">${[1,2,3].map(n=>`<option value="${n}" ${n===data.settings.level?'selected':''}>${[T('Inicial','Beginner','Inicial'),T('Intermedio','Intermediate','Intermediário'),T('Avanzado','Advanced','Avançado')][n-1]}</option>`).join('')}</select></label><label>${T('Preguntas por sesión','Questions per session','Perguntas por sessão')}<select id="questions">${[5,10].map(n=>`<option ${n===data.settings.questions?'selected':''}>${n}</option>`).join('')}</select></label></div>`;}
const practiceGroups=()=>[
 ['reading',T('Lectura','Reading','Leitura'),['reading','intervalTheory','keys']],
 ['ear',T('Oído','Ear','Ouvido'),['interval','scale','dictation']],
 ['harmony',T('Armonía','Harmony','Harmonia'),['chord','chordTheory','progression']],
 ['rhythm',T('Ritmo','Rhythm','Ritmo'),['rhythmTheory','rhythmDictation','rhythm']],
 ['voice',T('Voz y afinación','Voice & tuning','Voz e afinação'),['tuner','intonation']]];
const exerciseTitle=k=>k==='tuner'?T('Afinador','Tuner','Afinador'):kindTitle(k);
const exerciseDescription=k=>({reading:T('Notas naturales en claves de sol, fa y do.','Natural notes in treble, bass and alto clefs.','Notas naturais nas claves de sol, fá e dó.'),interval:T('Escucha dos notas y reconoce la distancia.','Hear two notes and identify the distance.','Ouça duas notas e reconheça a distância.'),chord:T('Distingue tríadas y acordes de séptima.','Distinguish triads and seventh chords.','Distinga tríades e acordes de sétima.'),scale:T('Reconoce escalas y modos al escucharlos.','Recognize scales and modes by listening.','Reconheça escalas e modos ao ouvir.'),dictation:T('Reproduce una secuencia de alturas con el teclado.','Rebuild a pitch sequence using the keyboard.','Reproduza uma sequência de alturas no teclado.'),intervalTheory:T('Lee dos notas y calcula el intervalo.','Read two notes and calculate the interval.','Leia duas notas e calcule o intervalo.'),chordTheory:T('Relaciona una escritura con la calidad del acorde.','Match notation to chord quality.','Relacione a escrita ao tipo de acorde.'),rhythmTheory:T('Lee figuras, puntillos y silencios.','Read note values, dots and rests.','Leia figuras, pontos de aumento e pausas.'),rhythmDictation:T('Escucha y elige el patrón escrito.','Listen and choose the written pattern.','Ouça e escolha o padrão escrito.'),keys:T('Reconoce armaduras mayores.','Recognize major key signatures.','Reconheça armaduras maiores.'),progression:T('Identifica recorridos armónicos al escucharlos.','Identify harmonic progressions by ear.','Identifique progressões harmônicas ao ouvir.'),rhythm:T('Escucha, marca el patrón y revisa tu precisión.','Listen, tap the pattern and review your timing.','Ouça, marque o padrão e confira sua precisão.')})[k]|| (k==='tuner'?T('Comprueba la afinación con micrófono.','Check tuning with a microphone.','Confira a afinação com microfone.'):T('Escucha, canta y compara la altura.','Listen, sing and compare pitch.','Ouça, cante e compare a altura.'));
const searchText=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const practiceSummary=()=>T('Opciones','Options','Opções')+' · '+T('Nivel','Level','Nível')+' '+data.settings.level+' · '+data.settings.questions+' '+T('preguntas','questions','perguntas');
function practiceMenu(){const groups=practiceGroups();$('view').innerHTML=`<h2>${T('Practicar','Practice','Praticar')}</h2><details class="panel practice-settings"><summary id="practiceSummary">${practiceSummary()}</summary>${controls()}${soundControls()}</details><label class="search-label"><span class="sr-only">${T('Buscar ejercicio','Find an exercise','Buscar exercício')}</span><input type="search" id="exerciseSearch" placeholder="${T('Buscar ejercicio…','Find an exercise…','Buscar exercício…')}" value="${H(practiceQuery)}"></label><div class="practice-filters" role="group" aria-label="${T('Áreas de práctica','Practice areas','Áreas de prática')}">${groups.map(([id,name])=>b(name,`data-group="${id}" aria-pressed="${id===practiceGroup}"`)).join('')}</div><p id="exerciseCount" class="small muted" role="status"></p><div class="exercise-list" id="exerciseList"></div>`;bindSoundControls();$('level').onchange=e=>{data.settings.level=Number(e.target.value);save();$('practiceSummary').textContent=practiceSummary();};$('questions').onchange=e=>{data.settings.questions=Number(e.target.value);save();$('practiceSummary').textContent=practiceSummary();};$('exerciseSearch').oninput=e=>{practiceQuery=e.target.value;drawExercises();};document.querySelectorAll('[data-group]').forEach(e=>e.onclick=()=>{practiceGroup=e.dataset.group;practiceQuery='';$('exerciseSearch').value='';drawExercises();});drawExercises();}
function drawExercises(){const groups=practiceGroups(),query=searchText(practiceQuery.trim()),all=groups.flatMap(g=>g[2]),selected=query?all:groups.find(g=>g[0]===practiceGroup)[2],visible=selected.filter(k=>!query||searchText(exerciseTitle(k)+' '+exerciseDescription(k)).includes(query));document.querySelectorAll('[data-group]').forEach(e=>e.setAttribute('aria-pressed',String(!query&&e.dataset.group===practiceGroup)));$('exerciseCount').textContent=visible.length+' '+(visible.length===1?T('ejercicio','exercise','exercício'):T('ejercicios','exercises','exercícios'))+(query?' · '+T('en todas las áreas','across all areas','em todas as áreas'):'');$('exerciseList').innerHTML=visible.map(k=>`<button type="button" class="exercise-row" ${['tuner','intonation'].includes(k)?`data-voice="${k}"`:`data-start="${k}"`}><span><strong>${H(exerciseTitle(k))}</strong><span class="row-description">${H(exerciseDescription(k))}</span></span><span aria-hidden="true">›</span></button>`).join('')||`<p>${T('No hay coincidencias. Prueba otro término o elige un área.','No matches. Try another term or choose an area.','Nenhum resultado. Tente outro termo ou escolha uma área.')}</p>`;bindRoutes();document.querySelectorAll('[data-voice]').forEach(e=>e.onclick=()=>voiceView(e.dataset.voice));}
function start(kind,level=data.settings.level){stop();$('view').dataset.screen='session';practiceGroup=practiceGroups().find(g=>g[2].includes(kind))[0];tab='practice';session={kind,level,total:data.settings.questions,index:0,scores:[],answered:false,q:null,entry:[]};document.querySelectorAll('[data-tab]').forEach(e=>e.setAttribute('aria-current',(e.dataset.tab===tab||(tab==='dictionary'&&e.dataset.tab==='lessons'))?'page':'false'));nextQuestion();}
function staff(q){const y=144-C.staffStep(q.answer,q.bottom)*10;let svg='<svg class="staff" viewBox="0 0 360 240" role="img" aria-label="'+T('Identifica la nota','Identify the note','Identifique a nota')+'">';for(let i=0;i<5;i++)svg+=`<line x1="38" y1="${144-i*20}" x2="325" y2="${144-i*20}" stroke="#32151d" stroke-width="2"/>`;if(y>144)for(let py=164;py<=y;py+=20)svg+=`<line x1="174" y1="${py}" x2="218" y2="${py}" stroke="#32151d" stroke-width="2"/>`;if(y<64)for(let py=44;py>=y;py-=20)svg+=`<line x1="174" y1="${py}" x2="218" y2="${py}" stroke="#32151d" stroke-width="2"/>`;const clef=q.clef==='treble'?'𝄞':q.clef==='bass'?'𝄢':'𝄡';return svg+`<text x="46" y="${q.clef==='treble'?133:q.clef==='bass'?98:121}" font-size="73" fill="#32151d">${clef}</text><ellipse cx="196" cy="${y}" rx="13" ry="9" transform="rotate(-15 196 ${y})" fill="#32151d"/></svg>`;}
function nextQuestion(){stop();if(!session)return;if(session.index>=session.total){finish();return;}session.q=C.question(session.kind,session.level);session.answered=false;session.entry=[];questionView();}
function questionView(){window.scrollTo(0,0);const s=session,q=s.q;const optionText=x=>s.kind==='reading'?N(x):['interval','intervalTheory'].includes(s.kind)?intervalLabel(x):s.kind==='rhythmTheory'?String(x)+' '+T('pulsos','beats','pulsos'):s.kind==='keys'?({C:N(60),G:N(67),D:N(62),A:N(69),E:N(64),F:N(65),Bb:data.settings.notation==='letters'?'B♭':T('Si♭','Si♭','Si♭'),Eb:data.settings.notation==='letters'?'E♭':T('Mi♭','Mi♭','Mi♭')}[x]+' '+T('mayor','major','maior')):s.kind==='progression'?x:chordAnswer(x,q);let body='';if(['reading','intervalTheory','chordTheory','keys'].includes(s.kind))body=`<p>${T('Clave','Clef','Clave')}: ${{treble:T('Sol','Treble','Sol'),bass:T('Fa','Bass','Fá'),alto:T('Do en tercera','Alto','Dó na terceira')}[q.clef]}</p>${window.AcademyNotation.staff(q,T('Lee la notación','Read the notation','Leia a notação'))}`;else body=`<p>${T('Escucha antes de responder. Puedes repetir. Los timbres son sintetizados.','Listen before answering. You can replay. Sounds are synthesized.','Ouça antes de responder. Você pode repetir. Os timbres são sintetizados.')}</p>`;
 if(s.kind==='rhythmTheory')body+=`<p>${T('Con negra = un pulso, ¿cuánto dura esta figura o silencio?','With quarter note = one beat, how long is this note or rest?','Com semínima = um pulso, quanto dura esta figura ou pausa?')}</p>${window.AcademyNotation.rhythm([q.rest?-q.figure:q.figure],T('Figura o silencio','Note value or rest','Figura ou pausa'),true)}`;
 if(q.options)body+=`<div class="choices">${q.options.map((o,i)=>s.kind==='rhythmDictation'?`<button type="button" data-answer="${i}" aria-label="${T('Patrón','Pattern','Padrão')} ${i+1}">${window.AcademyNotation.rhythm(o.split(',').map(Number),T('Patrón rítmico','Rhythm pattern','Padrão rítmico')+' '+(i+1))}</button>`:b(optionText(o),`data-answer="${i}"`)).join('')}</div>`;
 if(s.kind==='dictation')body+=`<p class="hint">${T('Solo alturas, no duración.','Pitch only, not duration.','Somente alturas, não duração.')} ${q.answer.length} ${T('notas','notes','notas')}</p><p class="sequence" id="entry" aria-live="polite">—</p><div id="entryScore"></div><div class="keyboard">${q.keyboard.map(n=>b(N(n),`data-note="${n}"`)).join('')}</div><div class="actions">${b(T('Deshacer','Undo','Desfazer'),'id="undoNote"')}${b(T('Comprobar','Check','Conferir'),'id="checkNotes" class="primary" disabled')}</div>`;
 if(s.kind==='rhythm')body+=`<p>${q.bpm} BPM · 4 ${T('pulsos','beats','pulsos')}</p>${window.AcademyNotation.rhythm(window.AcademyNotation.durations(q.answer),T('Patrón para reproducir','Pattern to reproduce','Padrão para reproduzir'))}<div class="beat-grid" aria-label="${T('Patrón en ocho subdivisiones','Pattern in eight subdivisions','Padrão em oito subdivisões')}">${Array.from({length:8},(_,i)=>`<span class="${q.answer.includes(i/2)?'on':''}">${q.answer.includes(i/2)?'●':'·'}</span>`).join('')}</div><p class="hint">${T('Escucha el ejemplo. Después inicia: cuenta cuatro pulsos y toca durante los cuatro siguientes. La latencia del dispositivo puede influir.','Listen to the example. Then start: count four beats and tap during the next four. Device latency can affect timing.','Ouça o exemplo. Depois comece: conte quatro pulsos e toque nos quatro seguintes. A latência do dispositivo pode influenciar.')}</p>${b(T('Iniciar cuenta y respuesta','Start count-in and response','Iniciar contagem e resposta'),'id="startTap" class="primary"')}<p id="tapStatus" role="status"></p><button class="tap" id="tap" type="button" disabled>${T('TOCA AQUÍ','TAP HERE','TOQUE AQUI')}</button>`;
 $('view').innerHTML=`<div class="session-toolbar">${b(T('← Práctica','← Practice','← Prática'),'id="exitSession"')}<label><span class="sr-only">${T('Cambiar ejercicio','Change exercise','Trocar exercício')}</span><select id="quickExercise">${practiceGroups().map(([,name,kinds])=>`<optgroup label="${H(name)}">${kinds.map(k=>`<option value="${k}" ${k===s.kind?'selected':''}>${H(exerciseTitle(k))}</option>`).join('')}</optgroup>`).join('')}</select></label></div><h2 class="sr-only">${H(kindTitle(s.kind))}</h2><div class="question-actions"><p class="eyebrow">${T('Pregunta','Question','Pergunta')} ${s.index+1} / ${s.total} · ${T('Nivel','Level','Nível')} ${s.level}</p>${['keys','rhythmTheory'].includes(s.kind)?'':b(T('Escuchar','Listen','Ouvir'),'id="listen"')}</div><section class="panel session-panel">${body}<p class="feedback" id="feedback" role="status"></p>${b(T('Siguiente','Next','Próxima'),'id="nextQuestion" class="primary" disabled')}</section>`;$('exitSession').onclick=()=>render('practice');$('quickExercise').onchange=e=>{const k=e.target.value;practiceQuery='';if(['tuner','intonation'].includes(k))voiceView(k);else start(k,session.level);};if($('listen'))$('listen').onclick=()=>hear(q);document.querySelectorAll('[data-answer]').forEach(e=>e.onclick=()=>{if(s.answered)return;const value=q.options[Number(e.dataset.answer)],correct=value===q.answer;e.classList.add(correct?'good':'bad');answer(correct?100:0,correct?T('Correcto.','Correct.','Correto.'):T('Respuesta: ','Answer: ','Resposta: ')+optionText(q.answer));});$('nextQuestion').onclick=()=>{s.index++;nextQuestion();};
 if(s.kind==='dictation'){const refresh=()=>{$('entryScore').innerHTML=s.entry.length?window.AcademyNotation.melody(s.entry,T('Tu melodía: solo alturas','Your melody: pitch only','Sua melodia: somente alturas')):'';$('entry').textContent=s.entry.map(n=>N(n)).join(' · ')||'—';$('checkNotes').disabled=s.entry.length!==q.answer.length;};document.querySelectorAll('[data-note]').forEach(e=>e.onclick=async()=>{if(s.answered||s.entry.length>=q.answer.length)return;const n=Number(e.dataset.note);s.entry.push(n);refresh();const ticket=audioEpoch;try{await audio();if(ticket!==audioEpoch||session!==s)return;tone(n,ctx.currentTime+.02,.4);}catch{say(T('Audio no disponible.','Audio unavailable.','Áudio indisponível.'));}});$('undoNote').onclick=()=>{if(!s.answered){s.entry.pop();refresh();}};$('checkNotes').onclick=()=>{const correct=s.entry.every((n,i)=>n===q.answer[i]);answer(correct?100:0,T('Secuencia: ','Sequence: ','Sequência: ')+q.answer.map(n=>N(n)).join(' · '));};}
 if(s.kind==='rhythm'){$('startTap').onclick=startTap;$('tap').onpointerdown=e=>{e.preventDefault();tap();};$('tap').onkeydown=e=>{if([' ','Enter'].includes(e.key)&&!e.repeat){e.preventDefault();tap();}};}}
function answer(score,message){stop();if(!session||session.answered)return;session.answered=true;session.scores.push(score);$('feedback').textContent=message;if(session.kind==='dictation')$('entryScore').innerHTML=window.AcademyNotation.melody(session.q.answer,T('Melodía correcta: solo alturas','Correct melody: pitch only','Melodia correta: somente alturas'));document.querySelectorAll('[data-answer]').forEach(e=>{if(session.q.options[Number(e.dataset.answer)]===session.q.answer)e.classList.add('good');});document.querySelectorAll('[data-answer],[data-note],#checkNotes,#undoNote,#startTap,#tap').forEach(e=>e.disabled=true);$('nextQuestion').disabled=false;if($('listen'))$('listen').disabled=true;if(data.settings.autoAdvance){const current=session,index=current.index;const pause=document.createElement('button');pause.textContent=T('Pausar avance automático','Pause automatic advance','Pausar avanço automático');let timer=setTimeout(()=>{if(session===current&&session.answered&&session.index===index){session.index++;nextQuestion();}},score===100?1400:2800);timers.push(timer);pause.onclick=()=>{clearTimeout(timer);pause.disabled=true;pause.textContent=T('Avance pausado','Advance paused','Avanço pausado');};$('feedback').after(pause);}}
async function startTap(){if(!session||session.answered)return;const q=session.q;stop();const ticket=audioEpoch;try{await audio();if(ticket!==audioEpoch||session?.q!==q)return;}catch{say(T('Activa el audio para continuar.','Enable audio to continue.','Ative o áudio para continuar.'));return;}const beat=60/q.bpm,begin=ctx.currentTime+.15;rhythm={start:begin+4*beat,taps:[]};$('startTap').disabled=true;$('listen').disabled=true;$('tapStatus').textContent=T('Cuenta: 1, 2, 3, 4…','Count: 1, 2, 3, 4…','Conte: 1, 2, 3, 4…');for(let i=0;i<4;i++)tone(i===0?88:82,begin+i*beat,.07,.65);timers.push(setTimeout(()=>{if(!rhythm)return;$('tap').disabled=false;$('tapStatus').textContent=T('Ahora: cuatro pulsos.','Now: four beats.','Agora: quatro pulsos.');},(rhythm.start-ctx.currentTime)*1000));timers.push(setTimeout(()=>{if(!rhythm)return;const result=C.evaluateRhythm(q.answer,rhythm.taps,q.bpm);answer(result.score,`${result.score}% · ${result.matched}/${result.expected} · ${result.meanMs===null?'—':result.meanMs+' ms'} ${T('error medio de los golpes detectados','mean error of matched taps','erro médio dos toques detectados')}`);},(rhythm.start+4*beat+.1-ctx.currentTime)*1000));}
function tap(){if(!rhythm||!ctx||ctx.currentTime<rhythm.start||$('tap').disabled)return;rhythm.taps.push(ctx.currentTime-rhythm.start);tone(76,ctx.currentTime,.05,.25);}
function finish(){const s=session;stop();const score=Math.round(s.scores.reduce((a,b)=>a+b,0)/s.total);data.sessions.push({id:crypto.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2),kind:s.kind,level:s.level,score,total:s.total,date:new Date().toISOString()});data.sessions=data.sessions.slice(-300);save();session=null;$('view').innerHTML=`<p class="eyebrow">${T('SESIÓN COMPLETADA','SESSION COMPLETE','SESSÃO CONCLUÍDA')}</p><h2>${H(kindTitle(s.kind))}</h2><section class="panel"><p class="metric">${score}%</p><p>${s.total} ${T('preguntas · resultado guardado localmente','questions · result saved locally','perguntas · resultado salvo localmente')}</p><p class="hint">${T('Este resultado orienta tu estudio; no certifica dominio ni sustituye una evaluación docente.','This result guides practice; it does not certify mastery or replace teacher assessment.','Este resultado orienta o estudo; não certifica domínio nem substitui uma avaliação docente.')}</p><div class="actions">${b(T('Otra sesión','Another session','Outra sessão'),`data-start="${s.kind}" class="primary"`)}${b(T('Ver progreso','View progress','Ver progresso'),'data-go="progress"')}</div></section>`;if(!storageOK)say(T('El resultado no se pudo guardar: exporta una copia.','Result could not be saved: export a backup.','Não foi possível salvar: exporte uma cópia.'));bindRoutes();}
function progress(){const l=data.settings.lang,avg=data.sessions.length?Math.round(data.sessions.reduce((a,s)=>a+s.score,0)/data.sessions.length):null;const days=new Set(data.sessions.map(s=>new Date(s.date).toLocaleDateString('en-CA'))).size;$('view').innerHTML=`<h2>${T('Tu progreso','Your progress','Seu progresso')}</h2><div class="grid">${card(T('Sesiones completas','Completed sessions','Sessões concluídas'),String(data.sessions.length),'')}${card(T('Días con práctica','Days practiced','Dias com prática'),String(days),'')}</div><p>${T('Promedio de sesiones','Session average','Média das sessões')}: ${avg===null?'—':avg+'%'} · ${data.lessons.length}/${lessons.length} ${T('lecciones','lessons','lições')}</p><section class="panel"><h3>${T('Por habilidad','By skill','Por habilidade')}</h3>${[...C.kinds,'intonation'].map(k=>{const a=data.sessions.filter(s=>s.kind===k).slice(-5),v=a.length?Math.round(a.reduce((x,y)=>x+y.score,0)/a.length):null;return `<p>${H(kindTitle(k))}: ${v===null?'—':v+'%'} <span class="small">(${a.length} ${T('últimas sesiones','recent sessions','sessões recentes')})</span></p>`;}).join('')}</section><div class="actions">${b(T('Exportar copia JSON','Export JSON backup','Exportar cópia JSON'),'id="backup" class="primary"')}<label>${T('Importar y combinar copia','Import and merge backup','Importar e combinar cópia')}<input id="restore" type="file" accept=".json,application/json"></label></div><p class="hint">${T('No hay sincronización en la nube. La copia conserva el historial y las lecciones; al combinar se mantienen tus ajustes actuales y no se duplican sesiones con el mismo identificador.','There is no cloud sync. Backups preserve history and lessons; merging keeps current settings and deduplicates session IDs.','Não há sincronização na nuvem. A cópia preserva histórico e lições; a combinação mantém os ajustes atuais e evita duplicar identificadores.')}</p><ol class="history">${data.sessions.slice(-20).reverse().map(s=>`<li>${H(new Date(s.date).toLocaleString(l))} · ${H(kindTitle(s.kind))} · ${s.score}% · ${T('Nivel','Level','Nível')} ${s.level}</li>`).join('')||T('Todavía no has completado sesiones.','No sessions completed yet.','Você ainda não concluiu sessões.')}</ol>`;$('backup').onclick=()=>download(JSON.stringify(data,null,2),'Walamort-Academy-backup.json');$('restore').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1024*1024)throw Error();const imported=C.validateBackup(JSON.parse(await file.text()),lessons.map(l=>l.id));data=C.mergeBackup(data,imported);const saved=save();progress();if(saved)say(T('Copia combinada.','Backup merged.','Cópia combinada.'));}catch{say(T('Copia no válida. No se modificó tu historial.','Invalid backup. Your history was not changed.','Cópia inválida. O histórico não foi alterado.'));}};}
function download(text,name){if(window.AcademyNative){window.AcademyNative.exportBackup(text,name).catch(()=>say(T('No se pudo preparar la copia.','Could not prepare the backup.','Não foi possível preparar a cópia.')));return;}const blob=new Blob([text],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function settings(){$('view').innerHTML=`<h2>${T('Tu experiencia','Your experience','Sua experiência')}</h2>${soundControls()}<section class="panel"><label>${T('Idioma','Language','Idioma')}<select id="language"><option value="es" ${data.settings.lang==='es'?'selected':''}>Español</option><option value="en" ${data.settings.lang==='en'?'selected':''}>English</option><option value="pt" ${data.settings.lang==='pt'?'selected':''}>Português (Brasil)</option></select></label><label>${T('Objetivo de la rutina','Routine goal','Objetivo da rotina')}<select id="goal">${[['beginner',T('Empezar desde cero','Start from scratch','Começar do zero')],['university',T('Preparación universitaria','University preparation','Preparação universitária')],['creative',T('Armonía y creación','Harmony and creation','Harmonia e criação')]].map(([v,t])=>`<option value="${v}" ${v===data.settings.goal?'selected':''}>${H(t)}</option>`).join('')}</select></label><label>${T('Minutos orientativos al día','Suggested minutes a day','Minutos sugeridos por dia')}<select id="minutes">${[5,10,15].map(n=>`<option ${n===data.settings.minutes?'selected':''}>${n}</option>`).join('')}</select></label><label>${T('Volumen de práctica','Practice volume','Volume de prática')}<input id="volume" type="range" min="0" max="1" step=".05" value="${data.settings.volume}"></label>${b(T('Probar sonido','Test sound','Testar som'),'id="testSound"')}</section><section class="panel"><h3>${T('Instalación y modo sin conexión','Installation and offline mode','Instalação e modo off-line')}</h3><p>${T('La primera carga necesita conexión. Cuando el núcleo esté guardado, vuelve a abrir la app para estudiar sin internet. El navegador puede eliminar datos si falta espacio; conserva una copia de progreso.','The first load needs a connection. Once the core is saved, reopen the app to study offline. Browsers may remove data under storage pressure; keep a progress backup.','A primeira carga precisa de conexão. Com o núcleo salvo, reabra a app para estudar off-line. O navegador pode apagar dados por falta de espaço; mantenha uma cópia do progresso.')}</p><p id="cacheInfo">${T('Comprobando…','Checking…','Verificando…')}</p></section><section class="panel"><h3>${T('Privacidad y límites','Privacy and scope','Privacidade e limites')}</h3><p>${T('Los ejercicios se calculan en el dispositivo. No hay cuenta, anuncios, analítica ni envío de respuestas. El micrófono es opcional y solo se solicita al activarlo; no se pide ubicación ni contactos. La web utiliza la conexión normal al alojamiento para descargar la app. Los sonidos son sintetizados.','Exercises run on the device. No account, ads, analytics or answer uploads. Microphone access is optional and requested only when enabled; no location or contacts are requested. Normal hosting connections download the app. Sounds are synthesized.','Os exercícios rodam no dispositivo. Sem conta, anúncios, analytics ou envio de respostas. O microfone é opcional e só é solicitado ao ativar; não pede localização nem contatos. A conexão normal com a hospedagem baixa a app. Os sons são sintetizados.')}</p><p>${T('El ritmo evalúa pulsaciones, no técnica instrumental. Lectura y dictado trabajan alturas; no son un examen universitario completo.','Rhythm evaluates taps, not instrumental technique. Reading and dictation train pitch; this is not a full university exam.','O ritmo avalia toques, não técnica instrumental. Leitura e ditado trabalham alturas; não é um exame universitário completo.')}</p></section><section class="panel"><h3>${T('Más herramientas de Walamort','More Walamort tools','Mais ferramentas Walamort')}</h3><p class="hint">${T('Estos enlaces abren la web y necesitan conexión.','These links open the website and need internet.','Estes links abrem o site e precisam de conexão.')}</p>${[['practica/',T('Catálogo completo de práctica','Full practice catalog','Catálogo completo de prática')],['dictado-pentagrama/',T('Dictado escrito en pentagrama','Written staff dictation','Ditado escrito no pentagrama')],['aula-docente/',T('Aula docente','Teacher planner','Planejador docente')],['produccion-musical/',T('Producción musical','Music production','Produção musical')],['privacidad/',T('Privacidad de la web','Website privacy','Privacidade do site')]].map(([url,t])=>`<a class="resource" target="_blank" rel="noopener noreferrer" href="https://walamort.com/${data.settings.lang==='en'?'en/':data.settings.lang==='pt'?'pt/':''}${url}">${H(t)} ↗</a>`).join('')}</section>`;bindSoundControls();if(rejectedData!==null){const raw=document.createElement('button');raw.textContent=T('Exportar historial original para recuperar','Export original history for recovery','Exportar histórico original para recuperar');raw.onclick=()=>download(rejectedData,'Walamort-Academy-original.json');$('view').prepend(raw);}$('language').onchange=e=>{data.settings.lang=e.target.value;save();render('settings');};for(const id of ['goal','minutes','volume'])$(id).onchange=e=>{data.settings[id]=id==='goal'?e.target.value:Number(e.target.value);save();};$('testSound').onclick=()=>hear({kind:'interval',notes:[60,64,67]});if(window.Capacitor?.isNativePlatform?.())$('cacheInfo').textContent=T('Contenido incluido en la app para uso sin conexión.','Content is bundled for offline use.','Conteúdo incluído na app para uso off-line.');else if(swRegistration)$('cacheInfo').textContent=swRegistration.active?T('Núcleo instalado para uso sin conexión.','Core installed for offline use.','Núcleo instalado para uso off-line.'):T('Preparando archivos…','Preparing files…','Preparando arquivos…');else $('cacheInfo').textContent=T('Sin confirmar. Mantén la conexión para la primera preparación.','Not confirmed. Stay online for initial preparation.','Não confirmado. Mantenha a conexão para a preparação inicial.');}
window.AcademyPause=()=>{const interrupted=!!rhythm;stop(true);if(interrupted&&session&&!session.answered)questionView();};window.addEventListener('pagehide',()=>stop(true));
window.AcademyBack=()=>{if($('installHelp').open){$('installHelp').close();return true;}if(session){render('practice');return true;}if(tab==='dictionary'){render('lessons');return true;}if(tab!=='home'){render('home');return true;}return false;};if(window.Capacitor?.isNativePlatform?.())$('install').hidden=true;
$('closeHelp').onclick=()=>$('installHelp').close();$('install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;return;}$('installTitle').textContent=T('Instalar Walamort Academy','Install Walamort Academy','Instalar Walamort Academy');$('installText').textContent=T('En Android/Chrome: abre el menú del navegador y elige «Instalar aplicación» o «Añadir a pantalla de inicio». En iPhone/Safari: Compartir → Añadir a pantalla de inicio. Si ya está instalada, ábrela desde su icono. La opción depende del navegador.','Android/Chrome: open the browser menu and choose Install app or Add to Home screen. iPhone/Safari: Share → Add to Home Screen. If already installed, open its icon. Options depend on the browser.','Android/Chrome: abra o menu e escolha Instalar app ou Adicionar à tela inicial. iPhone/Safari: Compartilhar → Adicionar à Tela de Início. Se já instalada, abra pelo ícone. A opção depende do navegador.');$('installHelp').showModal();};window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});window.addEventListener('online',connection);window.addEventListener('offline',connection);document.addEventListener('visibilitychange',()=>{if(document.hidden){const interrupted=!!rhythm;stop(true);if(interrupted&&session&&!session.answered){questionView();say(T('Práctica pausada al ocultar la app. Inicia otra cuenta.','Practice paused when the app was hidden. Start a new count-in.','Prática pausada ao ocultar a app. Inicie uma nova contagem.'));}}});document.querySelectorAll('[data-tab]').forEach(e=>e.onclick=()=>render(e.dataset.tab));
try{const response=await fetch('lessons.json');if(!response.ok)throw Error();lessons=await response.json();let stored=null;try{stored=localStorage.getItem(KEY);}catch{storageOK=false;}if(stored){try{data=C.validateBackup(JSON.parse(stored),lessons.map(l=>l.id));}catch{rejectedData=stored;say(T('No se pudo leer el historial anterior. Conserva una copia antes de guardar nuevos resultados.','Could not read previous history. Keep a backup before saving new results.','Não foi possível ler o histórico anterior. Guarde uma cópia antes de salvar novos resultados.'));}}const params=new URLSearchParams(location.search),requestedLanguage=params.get('lang');if(['es','en','pt'].includes(requestedLanguage))data.settings.lang=requestedLanguage;const initial=params.get('tab');render(['home','lessons','practice','progress','settings','dictionary'].includes(initial)?initial:'home');if(rejectedData!==null)say(T('Historial anterior no válido. Se conserva intacto; exporta el original en Ajustes.','Previous history is invalid. It is preserved; export the original in Settings.','Histórico anterior inválido. Foi preservado; exporte o original em Ajustes.'));}catch{$('view').innerHTML='<h2>Walamort Academy</h2><p>No se pudieron cargar las lecciones. Revisa tu conexión y vuelve a abrir la app. / Lessons could not load. Check your connection and reopen.</p>';return;}
if('serviceWorker'in navigator&&!window.Capacitor?.isNativePlatform?.()){try{swRegistration=await navigator.serviceWorker.register('sw.js',{scope:'./'});if(swRegistration.waiting)$('update').hidden=false;swRegistration.addEventListener('updatefound',()=>{const w=swRegistration.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)$('update').hidden=false;});});let updating=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(updating)location.reload();else connection();});$('update').onclick=()=>{stop();if(swRegistration.waiting){updating=true;$('update').disabled=true;swRegistration.waiting.postMessage({type:'ACTIVATE_UPDATE'});}};navigator.serviceWorker.ready.then(connection);}catch{say(T('El modo sin conexión no pudo prepararse. Puedes usar la app con internet.','Offline mode could not be prepared. You can use the app online.','Não foi possível preparar o modo off-line. Use a app com internet.'));}}
})();
